const { chromium } = require('playwright-core');
const assert = require('node:assert/strict');
(async () => {
 const [base,session,date,savedName,savedValue,adminSession] = process.argv.slice(2);
 const browser = await chromium.launch({executablePath:process.env.BROWSER_EXECUTABLE,headless:true,args:['--no-sandbox']});
 try {
  const context=await browser.newContext();
  await context.addCookies([{name:'session',value:session,url:base}]);
  const page=await context.newPage();
  for(const width of [1280,320]) {
   await page.setViewportSize({width,height:850});
   if(date==='generation') {
    await context.addCookies([{name:'session',value:adminSession,url:base}]);
    await page.goto(base+'/leases/report?reset=1');
    assert.equal(await page.locator('select[name="billing"] option[value="ungenerated"]').count(),1);
    await context.addCookies([{name:'session',value:session,url:base}]);
    await page.goto(base+'/leases/report?reset=1');
    assert.equal(await page.locator('select[name="billing"] option[value="ungenerated"]').count(),0);
    await page.getByLabel('Billing exception').selectOption('void');
    await page.getByRole('button',{name:'Refresh report'}).click();
    await page.getByRole('heading',{name:'Snapshot-linked details',exact:true}).waitFor();
    const response=await page.goto(base+'/leases/report?billing=ungenerated&search=Retained');
    assert.equal(response.status(),422);
    await page.waitForFunction(()=>document.activeElement?.hasAttribute('data-error-summary'));
    assert.match(await page.locator('[data-error-summary]').innerText(),/All Records Invoice and Pricing access, including archived Invoices/);
    assert.doesNotMatch(await page.locator('body').innerText(),/matching Leases/);
    assert.equal(await page.getByLabel('Search',{exact:true}).inputValue(),'Retained');
    assert.equal(await page.locator('select[name="billing"] option[value="ungenerated"]:not([disabled])').count(),0);
    await page.locator('[data-error-summary] a[href="#report-billing"]').click();
    await page.getByLabel('Billing exception').selectOption('review');
    await page.getByRole('button',{name:'Refresh report'}).click();
    await page.getByRole('heading',{name:'Snapshot-linked details',exact:true}).waitFor();
    await context.addCookies([{name:savedName,value:savedValue,domain:new URL(base).hostname,path:'/leases/report'}]);
    await page.goto(base+'/leases/report');
    assert.match(page.url(),/reset=1$/);
    assert.equal(await page.getByLabel('Billing exception').inputValue(),'');
    assert.equal(await page.locator('select[name="billing"] option[value="ungenerated"]').count(),0);
    assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=window.innerWidth),true);
    continue;
   }
   await page.goto(base+'/leases/report?as_of='+date+'&search=Historical');
   await page.getByRole('heading',{name:'Lease position report',exact:true}).waitFor();
   assert.equal(await page.getByLabel('As of company date').inputValue(),date);
   assert.equal(await page.getByLabel('Search',{exact:true}).inputValue(),'Historical');
   await page.getByRole('button',{name:'Refresh report'}).click();
   await page.waitForLoadState();
   assert.equal(await page.getByLabel('Search',{exact:true}).inputValue(),'Historical');
   assert.match(await page.locator('body').innerText(),/Updated at/);
   assert.match(await page.locator('body').innerText(),/1 matching Leases/);
   const detail=page.locator('a[href^="#lease-report-"]').first();
   await detail.click();
   assert.match(page.url(),/#lease-report-/);
   assert.equal(await page.getByLabel('As of company date').inputValue(),date);
   assert.equal(await page.getByLabel('Search',{exact:true}).inputValue(),'Historical');
   await page.reload();
   assert.equal(await page.getByLabel('Search',{exact:true}).inputValue(),'Historical');
   await page.goto(base+'/leases/report?as_of=bad&search=Historical');
   await page.locator('[data-error-summary]').waitFor();
   await page.waitForFunction(()=>document.activeElement?.hasAttribute('data-error-summary'));
   assert.equal(await page.getByLabel('As of company date').inputValue(),'bad');
   assert.equal(await page.getByLabel('Search',{exact:true}).inputValue(),'Historical');
   await page.locator('[data-error-summary] a[href="#report-as_of"]').click();
   await page.getByLabel('As of company date').fill(date);
   await page.getByRole('button',{name:'Refresh report'}).click();
   await page.getByRole('heading',{name:'Snapshot-linked details',exact:true}).waitFor();
   assert.match(await page.locator('body').innerText(),/1 matching Leases/);
   await page.goto(base+'/leases/report');
   assert.equal(await page.getByLabel('As of company date').inputValue(),date);
   assert.equal(await page.getByLabel('Search',{exact:true}).inputValue(),'Historical');
   await page.getByLabel('As of company date').fill('9999-12-31');
   await page.getByRole('button',{name:'Refresh report'}).click();
   await page.locator('[data-error-summary]').waitFor();
   assert.equal(await page.getByLabel('As of company date').inputValue(),'9999-12-31');
   await page.getByLabel('As of company date').fill(date);
   await page.getByRole('button',{name:'Refresh report'}).click();
   await page.getByRole('heading',{name:'Snapshot-linked details',exact:true}).waitFor();
   await page.route('**/leases/report?**', route=>route.abort('failed'));
   await page.getByRole('button',{name:'Refresh report'}).click();
   await page.getByRole('button',{name:'Retry results',exact:true}).waitFor();
   await page.unroute('**/leases/report?**');
   await page.getByRole('button',{name:'Retry results',exact:true}).click();
   await page.getByRole('heading',{name:'Snapshot-linked details',exact:true}).waitFor();
   assert.equal(await page.getByLabel('Search',{exact:true}).inputValue(),'Historical');
   await page.getByRole('link',{name:'Current Lease workspace',exact:true}).click();
   await page.waitForURL(/\/leases\/\d+$/);
   await page.goBack();
   await page.getByRole('heading',{name:'Snapshot-linked details',exact:true}).waitFor();
   assert.equal(await page.getByLabel('As of company date').inputValue(),date);
   assert.equal(await page.getByLabel('Search',{exact:true}).inputValue(),'Historical');
   assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=window.innerWidth),true);
  }
 } finally {await browser.close();}
})().catch(error=>{console.error(error);process.exit(1)});
